private string NormalizeYouTubeUrl(string strUrl)
{
    string strVideoId = GetYouTubeVideoId(strUrl);
    if (!string.IsNullOrEmpty(strVideoId))
        return string.Format("https://www.youtube.com/watch?v={0}", strVideoId);

    return strUrl;
}

private string GetYouTubeVideoId(string strUrl)
{
    if (string.IsNullOrEmpty(strUrl))
        return string.Empty;

    int intEmbedIndex = strUrl.IndexOf("youtube.com/embed/", StringComparison.OrdinalIgnoreCase);
    if (intEmbedIndex >= 0)
    {
        int intStart = intEmbedIndex + 18;
        int intEnd = strUrl.IndexOf("?", intStart);
        if (intEnd > intStart)
            return strUrl.Substring(intStart, intEnd - intStart);

        return strUrl.Substring(intStart);
    }

    int intWatchIndex = strUrl.IndexOf("v=", StringComparison.OrdinalIgnoreCase);
    if (intWatchIndex >= 0)
    {
        int intStart = intWatchIndex + 2;
        int intEnd = strUrl.IndexOf("&", intStart);
        if (intEnd > intStart)
            return strUrl.Substring(intStart, intEnd - intStart);

        return strUrl.Substring(intStart);
    }

    int intShortIndex = strUrl.IndexOf("youtu.be/", StringComparison.OrdinalIgnoreCase);
    if (intShortIndex >= 0)
    {
        int intStart = intShortIndex + 9;
        int intEnd = strUrl.IndexOf("?", intStart);
        if (intEnd > intStart)
            return strUrl.Substring(intStart, intEnd - intStart);

        return strUrl.Substring(intStart);
    }

    return string.Empty;
}

